import { _decorator, Component ,Node} from 'cc';
import { Bus } from './Engine/Bus';
import { World } from './Engine/World';
import { ViewRegistry } from './Engine/ViewRegistry';
import { FixedTick } from './Engine/Tick';
import { Bullet } from './Battle/Entity/Bullet';
import { MovementSystem } from './Battle/System/MovementSystem';
import { BulletView } from './Battle/View/BulletView';
import { OutOfBoundsSystem } from './Battle/System/OutOfBoundsSystem';

const { ccclass } = _decorator;

@ccclass('BattleTest')
export class BattleTest extends Component {

    start() {
        const bus = new Bus();
        const views = new ViewRegistry(this.node);   // 暂时没有 View，但需要传
        views.registerFactory('bullet',(e)=>{
            const node = new Node(`bullet_${e.id}`);
            return node.addComponent(BulletView);
        });

        const world = new World(bus, views);
        world.addSystem(new MovementSystem());
        world.addSystem(new OutOfBoundsSystem);

        // 手动创建 3 颗子弹，从底部往上飞
        for (let i = 0; i < 3; i++) {
            const b = new Bullet();
            b.x = -100 + i * 100;   // 横向错开
            b.y = 0;
            b.dirX = 0;             // 垂直向上
            b.dirY = 1;
            b.speed = 200;          // 每秒 200 像素
            b.damage = 10;
            b.isPlayerBullet = true;

            // ⚠️ ViewRegistry 没有 'bullet' 的工厂，attach 会 warn，但不会崩
            // attach 返回 null，子弹 Node 不会创建
            // 这里只验证数据层，不接 View
            world.add(b);
        }

        this._world = world;

        // 挂 FixedTick
        const tick = this.node.addComponent(FixedTick);
        tick.setup(world, views);
        tick.begin();

        // 每 0.5 秒打印一次子弹位置
        this.schedule(() => {
            const positions: string[] = [];
            for (const b of world.query<Bullet>('bullet')) {
                positions.push(`(${b.x.toFixed(1)}, ${b.y.toFixed(1)})`);
            }
            console.log(`[BattleTest] 子弹位置: ${positions.join(' | ')}`);
        }, 0.5);
    }

    private _world: World = null!;
}